describe("doctests of sympy.integrals.transforms", () => {
  it("cosine_transform(exp(-a*x), x, k)", () => {
    const [a, x, k] = symbols('a x k');
    expect(sympyStr(cosineTransform(exp(mul(-1, a, x)), x, k))).toBe('sqrt(2)*a/(sqrt(pi)*(a**2 + k**2))');
  });
  it("cosine_transform(exp(-a*sqrt(x))*cos(a*sqrt(x)), x, k)", () => {
    const [a, x, k] = symbols('a x k');
    expect(sympyStr(cosineTransform(mul(fn('cos', [mul(a, pow(x, rational(1, 2)))]), exp(mul(-1, a, pow(x, rational(1, 2))))), x, k))).toBe('a*exp(-a**2/(2*k))/(2*k**(3/2))');
  });
  it("fourier_transform(exp(-x**2), x, k)", () => {
    const [x, k] = symbols('x k');
    expect(sympyStr(fourierTransform(exp(mul(-1, pow(x, 2))), x, k))).toBe('sqrt(pi)*exp(-pi**2*k**2)');
  });
  // the arguments do not type-check against the public API
  //   fourier_transform(exp(-x**2), x, k, noconds=False)
  //   => (sqrt(pi)*exp(-pi**2*k**2), True)
  it.todo("fourier_transform(exp(-x**2), x, k, noconds=False)");
  it("inverse_hankel_transform(ht, k, r, nu)", () => {
    const [m, k, nu, r] = symbols('m k nu r');
    expect(sympyStr(inverseHankelTransform(mul(2, pow(2, mul(-1, m)), pow(k, add(-2, m)), pow(fn('gamma', [add(mul(rational(1, 2), m), mul(rational(1, 2), nu))]), -1), fn('gamma', [add(1, mul(rational(1, 2), nu), mul(rational(-1, 2), m))])), k, r, nu))).toBe('r**(-m)');
  });
  it("inverse_hankel_transform(ht, k, r, 0)", () => {
    const [a, k, r] = symbols('a k r');
    expect(sympyStr(inverseHankelTransform(mul(a, pow(k, -3), pow(add(1, mul(pow(a, 2), pow(k, -2))), rational(-3, 2))), k, r, rational(0)))).toBe('exp(-a*r)');
  });
  it("inverse_cosine_transform(sqrt(2)*a/(sqrt(pi)*(a**2 + k**2)), k, x)", () => {
    const [a, k, x] = symbols('a k x');
    expect(sympyStr(inverseCosineTransform(mul(a, pow(2, rational(1, 2)), pow(pi, rational(-1, 2)), pow(add(pow(a, 2), pow(k, 2)), -1)), k, x))).toBe('exp(-a*x)');
  });
  it("inverse_cosine_transform(1/sqrt(k), k, x)", () => {
    const [k, x] = symbols('k x');
    expect(sympyStr(inverseCosineTransform(pow(k, rational(-1, 2)), k, x))).toBe('1/sqrt(x)');
  });
  it("inverse_fourier_transform(sqrt(pi)*exp(-(pi*k)**2), k, x)", () => {
    const [k, x] = symbols('k x');
    expect(sympyStr(inverseFourierTransform(mul(pow(pi, rational(1, 2)), exp(mul(-1, pow(pi, 2), pow(k, 2)))), k, x))).toBe('exp(-x**2)');
  });
  // the arguments do not type-check against the public API
  //   inverse_fourier_transform(sqrt(pi)*exp(-(pi*k)**2), k, x, noconds=False)
  //   => (exp(-x**2), True)
  it.todo("inverse_fourier_transform(sqrt(pi)*exp(-(pi*k)**2), k, x, noconds=False)");
  it("inverse_hankel_transform(ht, k, r, nu) (2)", () => {
    const [m, k, nu, r] = symbols('m k nu r');
    expect(sympyStr(inverseHankelTransform(mul(2, pow(2, mul(-1, m)), pow(k, add(-2, m)), pow(fn('gamma', [add(mul(rational(1, 2), m), mul(rational(1, 2), nu))]), -1), fn('gamma', [add(1, mul(rational(1, 2), nu), mul(rational(-1, 2), m))])), k, r, nu))).toBe('r**(-m)');
  });
  it("inverse_hankel_transform(ht, k, r, 0) (2)", () => {
    const [a, k, r] = symbols('a k r');
    expect(sympyStr(inverseHankelTransform(mul(a, pow(k, -3), pow(add(1, mul(pow(a, 2), pow(k, -2))), rational(-3, 2))), k, r, rational(0)))).toBe('exp(-a*r)');
  });
  it("inverse_mellin_transform(gamma(s), s, x, (0, oo))", () => {
    const [s, x] = symbols('s x');
    expect(sympyStr(inverseMellinTransform(fn('gamma', [s]), s, x, [0, oo]))).toBe('exp(-x)');
  });
  it("inverse_mellin_transform(f, s, x, (-oo, -1))", () => {
    const [s, x] = symbols('s x');
    expect(sympyStr(inverseMellinTransform(pow(add(-1, pow(s, 2)), -1), s, x, [S.NegativeInfinity, -1]))).toBe('x*(1 - 1/x**2)*Heaviside(x - 1)/2');
  });
  it("inverse_mellin_transform(f, s, x, (-1, 1))", () => {
    const [s, x] = symbols('s x');
    expect(sympyStr(inverseMellinTransform(pow(add(-1, pow(s, 2)), -1), s, x, [-1, 1]))).toBe('-x*Heaviside(1 - x)/2 - Heaviside(x - 1)/(2*x)');
  });
  it("inverse_mellin_transform(f, s, x, (1, oo))", () => {
    const [s, x] = symbols('s x');
    expect(sympyStr(inverseMellinTransform(pow(add(-1, pow(s, 2)), -1), s, x, [1, oo]))).toBe('(1/2 - x**2/2)*Heaviside(1 - x)/x');
  });
  it("inverse_sine_transform(2**((1-2*a)/2)*k**(a - 1)*", () => {
    const [a, k, x] = symbols('a k x');
    expect(sympyStr(inverseSineTransform(mul(pow(2, add(rational(1, 2), mul(-1, a))), pow(k, add(-1, a)), pow(fn('gamma', [add(rational(1, 2), mul(rational(1, 2), a))]), -1), fn('gamma', [add(1, mul(rational(-1, 2), a))])), k, x))).toBe('x**(-a)');
  });
  it("inverse_sine_transform(sqrt(2)*k*exp(-k**2/(4*a))/(4*sqrt(a)**3), k, x)", () => {
    const [k, a, x] = symbols('k a x');
    expect(sympyStr(inverseSineTransform(mul(rational(1, 4), k, pow(2, rational(1, 2)), pow(a, rational(-3, 2)), exp(mul(rational(-1, 4), pow(a, -1), pow(k, 2)))), k, x))).toBe('x*exp(-a*x**2)');
  });
  // the arguments do not type-check against the public API
  //   mellin_transform(exp(-x), x, s)
  //   => (gamma(s), (0, oo), True)
  it.todo("mellin_transform(exp(-x), x, s)");
  it("sine_transform(x*exp(-a*x**2), x, k)", () => {
    const [x, a, k] = symbols('x a k');
    expect(sympyStr(sineTransform(mul(x, exp(mul(-1, a, pow(x, 2)))), x, k))).toBe('sqrt(2)*k*exp(-k**2/(4*a))/(4*a**(3/2))');
  });
  it("sine_transform(x**(-a), x, k)", () => {
    const [x, a, k] = symbols('x a k');
    expect(sympyStr(sineTransform(pow(x, mul(-1, a)), x, k))).toBe('2**(1/2 - a)*k**(a - 1)*gamma(1 - a/2)/gamma(a/2 + 1/2)');
  });
  it("ht", () => {
    const [r, m, k, nu] = symbols('r m k nu');
    expect(sympyStr(hankelTransform(pow(r, mul(-1, m)), r, k, nu))).toBe('2*k**(m - 2)*gamma(-m/2 + nu/2 + 1)/(2**m*gamma(m/2 + nu/2))');
  });
  it("ht (2)", () => {
    const [a, r, k] = symbols('a r k');
    expect(sympyStr(hankelTransform(exp(mul(-1, a, r)), r, k, rational(0)))).toBe('a/(k**3*(a**2/k**2 + 1)**(3/2))');
  });
  it("ht (3)", () => {
    const [r, m, k, nu] = symbols('r m k nu');
    expect(sympyStr(hankelTransform(pow(r, mul(-1, m)), r, k, nu))).toBe('2*k**(m - 2)*gamma(-m/2 + nu/2 + 1)/(2**m*gamma(m/2 + nu/2))');
  });
  it("ht (4)", () => {
    const [a, r, k] = symbols('a r k');
    expect(sympyStr(hankelTransform(exp(mul(-1, a, r)), r, k, rational(0)))).toBe('a/(k**3*(a**2/k**2 + 1)**(3/2))');
  });
});

